PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

ASK WHERE {
  VALUES (?film1 ?film2) { (<http://dbpedia.org/resource/The_Collector_(2002_film)> <http://dbpedia.org/resource/Gul%C3%AEstan,_Land_of_Roses>) }

  { ?film1 dbo:country ?c1 } UNION { ?film1 dbp:country ?c1 }
  { ?film2 dbo:country ?c2 } UNION { ?film2 dbp:country ?c2 }

  OPTIONAL { ?c1 rdfs:label ?lab1 . FILTER(langMatches(lang(?lab1), "en")) }
  OPTIONAL { ?c2 rdfs:label ?lab2 . FILTER(langMatches(lang(?lab2), "en")) }

  BIND(LCASE(STR(COALESCE(?lab1, ?c1))) AS ?s1)
  BIND(LCASE(STR(COALESCE(?lab2, ?c2))) AS ?s2)

  FILTER (?s1 = ?s2)
}

